def seed_master_products(db):
    """
    Seed or update all 162 authentic Khojati Ayurvedic products.
    Preserves ledger integrity and ensures all products are present.
    """
    from models import MovementType, Product, StockLedger

    inserted = 0
    updated = 0
    for item in ALL_KHOJATI_PRODUCTS:
        existing = db.query(Product).filter(
            (Product.barcode == item["code"]) | (Product.product_name == item["name"])
        ).first()

        if existing:
            existing.category = item["category"]
            existing.subcategory = item.get("subcategory")
            existing.unit = item["unit"]
            updated += 1
        else:
            new_p = Product(
                barcode=item["code"],
                product_name=item["name"],
                category=item["category"],
                subcategory=item.get("subcategory"),
                unit=item["unit"],
                current_stock=100,
                low_stock_threshold=20,
            )
            db.add(new_p)
            db.flush()

            ledger = StockLedger(
                product_id=new_p.id,
                movement_type=MovementType.INWARD_GRN,
                reference_number="INITIAL-STOCK-SEED",
                previous_balance=0,
                quantity_delta=100,
                new_balance=100,
                operator="System Init",
                notes=f"Catalog seed: {item['category']}",
            )
            db.add(ledger)
            inserted += 1

    db.commit()
    return inserted, updated

